  "implementation": "def solve(case):
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    dp = [0.0] * (budget + 1)
    for l, s in zip(lengths, scores):
        for w in range(budget, l - 1, -1):
            dp[w] = max(dp[w], dp[w - l] + s)
    return dp[budget]"
